--- a/src/index.js
+++ b/src/index.js
 // QueenOS worker-starter: a dependency-free router. No build step: every
 // src/**/*.js file is uploaded as an ES module, so imports must be relative.
 import { features } from "./features/index.js";

+const APP_NAME = "worker-starter";
+
 const json = (body, status = 200) =>
   new Response(JSON.stringify(body, null, 2) + "\n", {
     status,
     headers: { "content-type": "application/json; charset=utf-8" },
   });

+const html = (body, status = 200) =>
+  new Response(body, {
+    status,
+    headers: { "content-type": "text/html; charset=utf-8" },
+  });
+
+const statusPage = (featureSlugs) => `<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8" />
+  <meta name="viewport" content="width=device-width, initial-scale=1" />
+  <title>Status · ${APP_NAME}</title>
+  <style>
+    :root { color-scheme: light dark; }
+    * { box-sizing: border-box; }
+    body {
+      margin: 0;
+      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
+      background: #f4f6f8;
+      color: #1c2733;
+      display: grid;
+      place-items: center;
+      min-height: 100vh;
+      padding: 1.5rem;
+      line-height: 1.5;
+    }
+    .card {
+      background: #fff;
+      border-radius: 18px;
+      box-shadow: 0 12px 30px rgba(0,0,0,.08);
+      padding: 2.25rem 2.5rem;
+      max-width: 520px;
+      width: 100%;
+    }
+    .status {
+      display: inline-flex;
+      align-items: center;
+      gap: .55rem;
+      font-weight: 700;
+      color: #0f7a3d;
+    }
+    .dot {
+      width: 12px;
+      height: 12px;
+      border-radius: 50%;
+      background: #21a35c;
+      box-shadow: 0 0 0 4px rgba(33,163,92,.2);
+    }
+    h1 { font-size: 1.75rem; margin: 1rem 0 .25rem; }
+    .subtitle { margin: 0 0 1.5rem; color: #5b6b7b; }
+    .meta {
+      margin-top: 1.5rem;
+      border-top: 1px solid #e5e9ed;
+      padding-top: 1.25rem;
+      font-size: .95rem;
+      display: grid;
+      gap: .55rem;
+    }
+    .meta div { display: flex; justify-content: space-between; gap: 1rem; }
+    .meta span:first-child { color: #8a99a8; }
+    .features { list-style: none; margin: 0; padding: 0; }
+    .features li { padding: .35rem 0; }
+    .features a { color: #0b5cad; text-decoration: none; }
+    .features a:hover { text-decoration: underline; }
+    .footer { margin-top: 1.5rem; font-size: .85rem; color: #8a99a8; }
+    .footer a { color: #5b6b7b; }
+    @media (prefers-color-scheme: dark) {
+      body { background: #0f1419; color: #e8eef4; }
+      .card { background: #181f26; box-shadow: 0 12px 30px rgba(0,0,0,.25); }
+      .subtitle { color: #9eadbd; }
+      .meta { border-color: #26313a; }
+      .meta span:first-child { color: #748595; }
+      .features a { color: #58a6ff; }
+      .footer { color: #748595; }
+      .footer a { color: #9eadbd; }
+    }
+  </style>
+</head>
+<body>
+  <main class="card">
+    <div class="status"><span class="dot"></span> All systems operational</div>
+    <h1>${APP_NAME}</h1>
+    <p class="subtitle">Dependency-free Cloudflare Worker status page.</p>
+    <section>
+      <h2 style="font-size:1.1rem;margin:0 0 .5rem">Active features</h2>
+      ${featureSlugs.length
+        ? `<ul class="features">${featureSlugs.map((s) => `<li><a href="/features/${s}">/features/${s}</a></li>`).join("")}</ul>`
+        : `<p class="subtitle">No features registered.</p>`}
+    </section>
+    <div class="meta">
+      <div><span>App</span><span>${APP_NAME}</span></div>
+      <div><span>Feature count</span><span>${featureSlugs.length}</span></div>
+    </div>
+    <p class="footer">Machine-readable health check: <a href="/health">/health</a></p>
+  </main>
+</body>
+</html>`;
+
 export default {
   async fetch(request) {
     const url = new URL(request.url);
     try {
       // Feature guards run on every request (auth, flags, rate limits, ...).
       for (const feature of features) {
         if (typeof feature.guard === "function") await feature.guard(request);
       }

       if (url.pathname === "/" || url.pathname === "") {
+        return html(statusPage(features.map((f) => f.slug)));
-        return json({ ok: true, app: "worker-starter", features: features.map((f) => f.slug) });
       }
       if (url.pathname === "/health") return json({ ok: true });

       const match = /^\/features\/([a-z0-9-]+)\/?$/.exec(url.pathname);
       if (match) {
         const feature = features.find((f) => f.slug === match[1]);
         if (feature) return await feature.handle(request);
       }
       return json({ ok: false, error: "not found", path: url.pathname }, 404);
     } catch (err) {
       return json({ ok: false, error: String((err && err.message) || err) }, 500);
     }
   },
 };
